function dir$smail(p){
  this.constructor(p);
    document._dir = p;
}
dir$smail.prototype = new DirEvent();
dir$smail.prototype.beforeInit = function(renderType){
  this._dir.options._files = null;
}

dir$smail.prototype.afterInit = function(renderType){
	const inputEmailBody = document.querySelector("textarea.email_body");
	const editorTextarea = document.querySelector("textarea.email_body_con");

	<!-- setTimeout(function() {		 -->
		<!-- var mota = document.querySelector('textarea.email_body_con') -->
		<!-- editor_mota = CKEDITOR.replace(mota, { -->
			<!-- customConfig: '/ckeditor/config.js', -->
			<!-- extraAllowedContent: 'span', -->
			<!-- maxLength: 256,  -->
		<!-- });	 -->
		<!-- editor_mota.setData(document.querySelector('input.mo_ta').value); -->
		<!-- editor_mota.on('change', function () { -->
			<!-- p.valForm('mo_ta', editor_mota.getData(), true); -->
		<!-- }); -->
	<!-- }, 500); -->

	ClassicEditor.create(editorTextarea, {
		toolbar: {
			items: [
				"heading", "|",
				"bold", "italic", "link",
				"bulletedList", "numberedList", "|",
				"indent", "outdent", "|",
				"imageUpload", "blockQuote", "mediaEmbed", "undo", "redo"
			]
		},
		language: "en",
		simpleUpload: {
			uploadUrl: "/AppHandler/SimpleUpload.ashx"
		}
	})
	.then(editor => {
		window.editor = editor;
		editor.setData(document.querySelector("textarea.email_body").value);
		editor.model.document.on("change:data", () => {
			document.querySelector("textarea.email_body").value = editor.getData();
		});
	})
	.catch(error => {
		console.error("CKEditor error:", error);
	});

	var p = this._dir, g = p.grid();

	//if (p.options.action == "NEW") p.valForm('email_body', 'Kính gửi: @ten_kh@', true);

	var exp = {	 
		t_chon_yn: ['@t_chon_yn', '[chon_yn]'],
	}

	p.applyExpression(exp, g, false);

	g.FomulaApplied = {
		"chon_yn":["t_chon_yn"]
	}

	dir$smailDisabledMasterField(p, g);
	dir$smailHiddenColumnByType(p);
	dir$smailHiddenColumnByTran(p);
	dir$smailDisabledStatusByAction(p);
}

dir$smail.prototype.beforeButtonDialogClick = function (id) {
	var p = this._dir, g = p.grid(0), dt = g.data;
	switch (id) {
		case 'ok':
			var d = p.valForm('ngay_hl'),d2 = p.valForm('ngay_hld');
			var k = $.date(d,"dd/mm/yy"),k2 = $.date(d2,"dd/mm/yy");
			if (p.valForm('ngay_hld') <= p.valForm('ngay_hl')) { 
				$.alert(p.msg('noDate')+' ' + k + ' < ' + k2);			
				return false;
			}
		default:
			break;
	}
	return true;
}
dir$smail.prototype.beforeButtonGridClick = function (id, gindex) {
	var p = this._dir;
	switch (id) {
		case '10':
			p.showFilter("smailKH", null, {_ngay_ct2: p.valForm('ngay_ct'),_unit_id: p.valForm('unit_id')});	  
			return false;
			break;
		default:
			break;
	}
	return true;
}

dir$smail.prototype.gridCellValueChange = function (o, g, r, c, v) {
  var p = this._dir;
  switch (c){
	case 'ma_kh' :
		p.grequest(g, 'ma_kh_request', '', ['ma_kh'], null, r);
	break;
    default:
      break;
  }
}
dir$smail.prototype.formFieldValueChange = function (o, cF, v) {
  var p = this._dir;
  switch (cF){
    case 'ma_gd':
      dir$smailHiddenColumnByTran(p);
      break;
    case 'ma_ngv':
      dir$smailHiddenColumnByType(p);
      break;

    default:
      break;
  }
}
dir$smail.prototype.gridDetailActionChange = function(gindex, action, r){
  var p = this._dir;
  if (action == 'AfterDeleteRow' || action == 'AfterAppendGrid') dir$smailDisabledMasterField(p, p.grid(gindex));
  return true;
}
